INSERT INTO `rooms` (`id`, `name`, `slug`, `tagline`, `description`, `price_per_night`, `size_sqm`, `bed_type`, `capacity_adults`, `capacity_children`, `view_type`, `image_url`, `gallery_json`, `amenities_json`, `translations_json`, `status`, `is_featured`, `display_order`) VALUES
(1, 'Deluxe King Room', 'deluxe-king', 'Contemporary Sanctuary for Modern Travelers', 'With modern and functional decor, our Deluxe King Room offers a serene and cozy environment perfect for unwinding and relaxation. Features a plush king-sized bed, high-speed WiFi, flat-screen smart TV, private minibar, artisan coffee station, and a luxurious en-suite bathroom stocked with organic bath amenities.', 85.00, 38, '1 King Bed', 2, 1, 'City View', 'https://lh3.googleusercontent.com/aida/AP1WRLs-aT78HuC87zVBtlw78IAcVeqttvz1DzuDCFkgHQa0GjAqpJ7QEgkbAcIsJqkihNQyvb5xyVUyfpGCLZpUTsGnoI_Zd2-vfG3hGgzgX8ILxOjMzXh6zptxCM2mUT_5SpyirJMD2KE7cfOEm3QbJ69fnH6VMjX0sVrsXmM5Jm-XtIvZg9-B3Mseq2ffcjkq7LNDstvkdy5lRLn-NIFXZWhKbwJ1tFsvSH-_tFiOrkWNTCNfDxbD8XbxG-j2', '["https://lh3.googleusercontent.com/aida/AP1WRLs-aT78HuC87zVBtlw78IAcVeqttvz1DzuDCFkgHQa0GjAqpJ7QEgkbAcIsJqkihNQyvb5xyVUyfpGCLZpUTsGnoI_Zd2-vfG3hGgzgX8ILxOjMzXh6zptxCM2mUT_5SpyirJMD2KE7cfOEm3QbJ69fnH6VMjX0sVrsXmM5Jm-XtIvZg9-B3Mseq2ffcjkq7LNDstvkdy5lRLn-NIFXZWhKbwJ1tFsvSH-_tFiOrkWNTCNfDxbD8XbxG-j2","https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&w=1200&q=80","https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?auto=format&fit=crop&w=1200&q=80"]', '["High-Speed Wi-Fi","55\" Smart Cable TV","Artisan Coffee Maker","Minibar & Refrigerator","In-Room Electronic Safe","Air Conditioning","Organic Bath Amenities","Rainfall Shower","Work Desk & Ergonomic Chair","Daily Housekeeping"]', '{"en":{"name":"Deluxe King Room","tagline":"Contemporary Sanctuary for Modern Travelers","description":"With modern and functional decor, our Deluxe King Room offers a serene and cozy environment perfect for unwinding and relaxation. Features a plush king-sized bed, high-speed WiFi, flat-screen smart TV, private minibar, artisan coffee station, and a luxurious en-suite bathroom."},"km":{"name":"បន្ទប់ ឌីឡាក់ឃីង (Deluxe King)","tagline":"ទីជម្រកដ៏ស្ងប់ស្ងាត់សម្រាប់អ្នកដំណើរទាន់សម័យ","description":"ជាមួយនឹងការតុបតែងបែបទំនើប និងមានមុខងារ បន្ទប់ ឌីឡាក់ឃីង របស់យើងផ្តល់នូវបរិយាកាសស្ងប់ស្ងាត់ និងកក់ក្តៅ ស័ក្តិសមបំផុតសម្រាប់ការសម្រាកលំហែកាយ។ បំពាក់ដោយគ្រែឃីងដ៏មានផាសុកភាព អ៊ីនធឺណិតល្បឿនលឿន ទូរទស្សន៍ឆ្លាតវៃ មីនីបារ និងបន្ទប់ទឹកប្រណិត។"},"zh":{"name":"豪华大床房 (Deluxe King)","tagline":"专为现代商务与休闲旅客打造的当代庇护所","description":"豪华大床房拥有现代实用的装潢，营造出宁静舒适的居停环境，是放松身心的理想之选。配有豪华特大床、高速无线网络、智能液晶电视、私人迷你吧、手冲咖啡台以及配备有机洗浴用品的典雅卫浴。"},"ko":{"name":"디럭스 킹 룸 (Deluxe King)","tagline":"현대 여행자를 위한 도심 속 안식처","description":"모던하고 실용적인 인테리어를 갖춘 디럭스 킹 룸은 휴식과 재충전을 위한 평온하고 아늑한 분위기를 제공합니다. 고급 킹사이즈 침대, 초고속 와이파이, 스마트 TV, 미니바 및 오가닉 어메니티를 구비하고 있습니다."}}', 'available', 1, 1),
INSERT INTO `dining_wellness` (`id`, `type`, `title`, `subtitle`, `description`, `hours`, `price_range`, `image_url`, `menu_items_json`, `is_published`, `display_order`) VALUES
(1, 'dining', 'The Indra Bistro & Cafe', 'Artisanal Coffee & Contemporary International Dining', 'Indulge in a range of culinary experiences featuring international and Asian-fusion cuisine with a contemporary twist. From a delectable breakfast at the cafe to fine dining and sunset cocktails, our sophisticated surroundings provide the perfect backdrop for an unforgettable dining experience.', '06:30 AM - 10:30 PM', '$$ - $$$', 'https://lh3.googleusercontent.com/aida/AP1WRLu4xqDm5eXV-bc_ApYrUK1GnN0Euq-6ES4WN642l6K8VhewdBb_YkEtWSSt-tybo0AKJFBQh2oRWlfCx42rbsSmJsLPSmn2ODfXDog-y3cHuE5NTuWtSDiZptOZNk-bMlpk3s-xS7TRQHWRaUeUH0_bRiicGwQeGjy6gBDbaO4KosbM7QsKUNWT0PhQSHXUnhupahrd4i6fqtDtt53ZX2XGRn06_VQba3YHrkQ1BSNwkc5KeAJ3nMpX63ho', '[{"name":"Traditional Khmer Fish Amok","price":"$14.00","desc":"Steamed sea bass fillet in rich aromatic coconut lemongrass curry served in banana leaf."},{"name":"Angus Ribeye Steak 250g","price":"$28.00","desc":"Char-grilled prime beef served with Kampot green peppercorn sauce and truffle mashed potatoes."},{"name":"Signature Indra Benedict","price":"$9.50","desc":"Poached farm eggs, smoked salmon, avocado, brioche bun, and homemade yuzu hollandaise."},{"name":"Kampot Pepper Crab Fried Rice","price":"$12.50","desc":"Fragrant Jasmine rice wok-tossed with fresh blue crab meat, garlic, and fresh Kampot pepper."}]', 1, 1),
INSERT INTO `special_offers` (`id`, `title`, `promo_code`, `discount_percent`, `description`, `valid_from`, `valid_to`, `image_url`, `badge_text`, `is_active`, `display_order`) VALUES
(1, 'Direct Booking Privilege', 'INDRA15', 15, 'Book your stay directly on our official website and enjoy an exclusive 15% discount across all suites, complimentary daily breakfast, and flexible cancellation up to 24 hours prior to arrival.', '2026-01-01', '2026-12-31', 'https://images.unsplash.com/photo-1571896349842-33c89424de2d?auto=format&fit=crop&w=1000&q=80', 'Best Rate Guarantee', 1, 1),
(2, 'Romantic Suite Getaway', 'LOVEINDRA', 20, 'Escape for a romantic getaway in our Indra Suite with Balcony. Includes a bottle of chilled sparkling wine on arrival, floral bed decoration, and late checkout until 3:00 PM.', '2026-02-01', '2026-12-31', 'https://images.unsplash.com/photo-1596394516093-501ba68a0ba6?auto=format&fit=crop&w=1000&q=80', 'Romantic Experience', 1, 2),
(3, 'Long Stay Sanctuary Package', 'STAYLONG', 25, 'Stay 5 nights or more and receive 25% off nightly rates, complimentary weekly laundry service, and 20% off all dining and spa treatments during your stay.', '2026-01-01', '2026-12-31', 'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=1000&q=80', 'Extended Stay', 1, 3)
