INSERT INTO `messages` (`id`, `name`, `email`, `phone`, `subject`, `message`, `status`, `created_at`) VALUES
(1, 'Michael Brown', 'michael.b@consulting.co', '+855 98 765 432', 'Airport Pickup & Suite Inquiry', 'Hello Indra Hotel Team, I am visiting Phnom Penh next week for business and would like to confirm if your Indra Suite has a high-speed wired Ethernet connection and whether airport pickup can be arranged? Thank you!', 'unread', '2026-08-17 14:22:00'),
(2, 'Claire Dubois', 'claire.dubois@paris.fr', '+33 6 12 34 56 78', 'Romantic Anniversary Dinner Reservation', 'Good afternoon, we will be staying in your Junior Suite on August 26th for our 10th wedding anniversary. Could we arrange a special rooftop table and flowers at The Bistro? Best regards, Claire', 'read', '2026-08-16 11:05:00')
